// Generated by MarrowScript compiler. DO NOT EDIT.
// Cognition Layer Phase 4 — TypeScript symbol extractor + index loader.
//
// Two backends:
//   memory (default): walks the source tree at startup and holds the graph
//                     in process. Cheap for small / medium repos.
//   pg              : queries Postgres tables populated by bin/index_sources.ts
//                     so multiple workers share an index without re-walking.
//
// LLM_MEMORY_BACKEND switches modes; LLM_MEMORY_ROOT (default: process.cwd())
// is the indexed root. Files matching LLM_MEMORY_EXCLUDE (default:
// node_modules, dist, .git, build) are skipped.
//
// Determinism: file walk is sorted, BFS expansion is sorted, and ids are
// derived from sha256 hashes. Two runs against the same tree produce
// identical graphs.

import * as fs from "fs";
import * as path from "path";
import { createHash } from "crypto";
import type { Symbol, SymbolKind, ImportEdge, FileSummary } from "./types";

// Lazy import of typescript so the memory layer doesn't force the dep
// when only file-level retrieval is needed (see PythonStrategy below for
// the language-extension hook). The TS compiler API is the canonical
// AST source — anything regex-based is too brittle for export tracking.
function loadTypescript(): typeof import("typescript") | null {
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    return require("typescript") as typeof import("typescript");
  } catch {
    return null;
  }
}

export function deriveSymbolId(file: string, name: string, line: number): string {
  return createHash("sha256").update(`${file}#${name}@${line}`).digest("hex").slice(0, 32);
}

export function approxTokens(s: string): number { return Math.ceil(s.length / 4); }

/** Sorted, deterministic recursive walk over a project root. */
export function listSourceFiles(root: string, excludes: string[]): string[] {
  const result: string[] = [];
  const stack: string[] = [root];
  const seen = new Set<string>();
  while (stack.length) {
    const dir = stack.pop()!;
    let entries: fs.Dirent[];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); }
    catch { continue; }
    entries.sort((a, b) => a.name.localeCompare(b.name));
    for (const e of entries) {
      const full = path.join(dir, e.name);
      const rel = path.relative(root, full).replace(/\\/g, "/");
      if (excludes.some(x => rel === x || rel.startsWith(x + "/"))) continue;
      if (e.isDirectory()) {
        stack.push(full);
      } else if (e.isFile() && /\.(ts|tsx|js|jsx|mts|cts)$/.test(e.name)) {
        if (seen.has(rel)) continue;
        seen.add(rel);
        result.push(rel);
      }
    }
  }
  return result.sort();
}

interface ExtractedFile {
  file: string;
  content_hash: string;
  symbols: Symbol[];
  imports: string[];
  token_count: number;
}

export function extractFile(absPath: string, relPath: string): ExtractedFile {
  const content = fs.readFileSync(absPath, "utf-8");
  const content_hash = createHash("sha256").update(content).digest("hex").slice(0, 32);
  const ts = loadTypescript();
  if (ts) return extractWithTypescript(ts, content, content_hash, relPath);
  return extractWithRegex(content, content_hash, relPath);
}

function extractWithTypescript(
  ts: typeof import("typescript"),
  content: string,
  content_hash: string,
  file: string,
): ExtractedFile {
  const sf = ts.createSourceFile(file, content, ts.ScriptTarget.Latest, true);
  const symbols: Symbol[] = [];
  const imports: string[] = [];

  function lineOf(pos: number): number { return sf.getLineAndCharacterOfPosition(pos).line + 1; }
  function colOf(pos: number): number { return sf.getLineAndCharacterOfPosition(pos).character; }

  function visibilityOf(node: import("typescript").Node): "public" | "internal" | "private" {
    const text = node.getText(sf).slice(0, 64);
    if (text.startsWith("export ") || text.includes("\nexport ")) return "public";
    if (text.startsWith("private ")) return "private";
    return "internal";
  }

  function pushSymbol(name: string, kind: SymbolKind, node: import("typescript").Node, signature?: string) {
    const line = lineOf(node.getStart(sf));
    symbols.push({
      id: deriveSymbolId(file, name, line),
      // Phase 10: repo_id is set by buildIndex() when it stamps each
      // symbol. The extractor doesn't know the repo identity (it's
      // file-local), so we initialise to '' and let buildIndex spread
      // the right value over the result.
      repo_id: "",
      file,
      name,
      kind,
      line,
      col: colOf(node.getStart(sf)),
      visibility: visibilityOf(node),
      signature: signature ?? null,
      doc_excerpt: null,
    });
  }

  function visit(node: import("typescript").Node) {
    // Imports / re-exports — record the resolved path string.
    if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier)) {
      imports.push(node.moduleSpecifier.text);
    } else if (ts.isExportDeclaration(node) && node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier)) {
      imports.push(node.moduleSpecifier.text);
    }
    // Top-level decls — narrow set, the kinds the retriever cares about.
    if (ts.isFunctionDeclaration(node) && node.name) {
      pushSymbol(node.name.text, "function", node, node.getText(sf).slice(0, 200));
    } else if (ts.isClassDeclaration(node) && node.name) {
      pushSymbol(node.name.text, "class", node);
      for (const m of node.members) {
        if (ts.isMethodDeclaration(m) && ts.isIdentifier(m.name)) {
          pushSymbol(`${node.name.text}.${m.name.text}`, "method", m, m.getText(sf).slice(0, 160));
        }
      }
    } else if (ts.isInterfaceDeclaration(node)) {
      pushSymbol(node.name.text, "interface", node);
    } else if (ts.isTypeAliasDeclaration(node)) {
      pushSymbol(node.name.text, "type", node);
    } else if (ts.isEnumDeclaration(node)) {
      pushSymbol(node.name.text, "enum", node);
    } else if (ts.isModuleDeclaration(node) && ts.isIdentifier(node.name)) {
      pushSymbol(node.name.text, "namespace", node);
    } else if (ts.isVariableStatement(node)) {
      for (const decl of node.declarationList.declarations) {
        if (ts.isIdentifier(decl.name)) {
          const isConst = (node.declarationList.flags & ts.NodeFlags.Const) !== 0;
          pushSymbol(decl.name.text, isConst ? "const" : "variable", decl);
        }
      }
    }
    ts.forEachChild(node, visit);
  }
  visit(sf);

  return {
    file,
    content_hash,
    symbols: symbols.sort((a, b) => a.line - b.line || a.name.localeCompare(b.name)),
    imports: [...new Set(imports)].sort(),
    token_count: approxTokens(content),
  };
}

function extractWithRegex(content: string, content_hash: string, file: string): ExtractedFile {
  const symbols: Symbol[] = [];
  const imports: string[] = [];
  const lines = content.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const importMatch = line.match(/^\s*import\s+.*?from\s+["']([^"']+)["']/);
    if (importMatch) imports.push(importMatch[1]);
    const decl = line.match(/^\s*(?:export\s+)?(?:async\s+)?(function|class|interface|type|enum|const|let|var)\s+([A-Za-z_$][A-Za-z0-9_$]*)/);
    if (decl) {
      const kindRaw = decl[1];
      const name = decl[2];
      const kind: SymbolKind = (kindRaw === "const" || kindRaw === "let" || kindRaw === "var")
        ? (kindRaw === "const" ? "const" : "variable")
        : (kindRaw as SymbolKind);
      symbols.push({
        id: deriveSymbolId(file, name, i + 1),
        repo_id: "",
        file, name, kind,
        line: i + 1,
        col: 0,
        visibility: line.includes("export") ? "public" : "internal",
        signature: line.trim().slice(0, 200),
        doc_excerpt: null,
      });
    }
  }
  return { file, content_hash, symbols, imports: [...new Set(imports)].sort(), token_count: approxTokens(content) };
}

export function resolveImport(fromFile: string, spec: string, root: string, allFiles: string[]): string | null {
  if (!spec.startsWith(".")) return null;
  const baseDir = path.dirname(path.join(root, fromFile));
  const target = path.resolve(baseDir, spec);
  const rel = path.relative(root, target).replace(/\\/g, "/");
  // Try with extensions and /index.* in deterministic order.
  const candidates = [
    rel, rel + ".ts", rel + ".tsx", rel + ".js",
    rel + "/index.ts", rel + "/index.tsx", rel + "/index.js",
  ];
  for (const c of candidates) {
    if (allFiles.includes(c)) return c;
  }
  return null;
}

export interface IndexedRepo {
  files: string[];
  symbolsByFile: Map<string, Symbol[]>;
  importsByFile: Map<string, string[]>;
  reverseImports: Map<string, string[]>;
  fileSummaries: Map<string, FileSummary>;
}

export function buildIndex(root: string, excludes: string[] = ["node_modules", "dist", ".git", "build", ".next", "output"], repo_id: string = ""): IndexedRepo {
  const files = listSourceFiles(root, excludes);
  const symbolsByFile = new Map<string, Symbol[]>();
  const importsByFile = new Map<string, string[]>();
  const reverseImports = new Map<string, string[]>();
  const fileSummaries = new Map<string, FileSummary>();

  // Pass 1: extract symbols + raw module specifiers per file.
  const rawImports = new Map<string, string[]>();
  for (const rel of files) {
    const ext = extractFile(path.join(root, rel), rel);
    // Stamp every extracted symbol with the repo_id (Phase 10).
    const stamped = ext.symbols.map(s => ({ ...s, repo_id }));
    symbolsByFile.set(rel, stamped);
    rawImports.set(rel, ext.imports);
    fileSummaries.set(rel, {
      repo_id, file: rel, content_hash: ext.content_hash, token_count: ext.token_count, summary: null,
    });
  }

  // Pass 2: resolve imports against the file set.
  for (const rel of files) {
    const resolved: string[] = [];
    for (const spec of rawImports.get(rel) || []) {
      const r = resolveImport(rel, spec, root, files);
      if (r) resolved.push(r);
    }
    const sortedResolved = [...new Set(resolved)].sort();
    importsByFile.set(rel, sortedResolved);
    for (const r of sortedResolved) {
      const arr = reverseImports.get(r) || [];
      arr.push(rel);
      reverseImports.set(r, arr);
    }
  }
  for (const [k, arr] of reverseImports) reverseImports.set(k, arr.sort());

  return { files, symbolsByFile, importsByFile, reverseImports, fileSummaries };
}
